//전체데이터 합치기
const merged = [...context.result, ..._result];

//중복파일 이름 제거
const uniqueFileNames = [...new Set(merged.map(item => item.filename))];
context.fileNames = uniqueFileNames;

//파일 이름별로 중복 데이터 합치기
const grouped = uniqueFileNames.map(name => {
    const filtered = merged.filter(r => r.filename === name);
    return {
        filename: name,
        content: filtered.map(v => v.content).join("\n"),
        range: filtered.map(v => v.range).join("\n")
    };
});

grouped;

